from itertools import product

# Generate all possible binary sequences of length 23
sequences = list(product([-1, 1], repeat=23))

# Filter sequences that sum to 1
valid_sequences = [seq for seq in sequences if sum(seq) == 1]

# Check for Legendre pairs
for x in valid_sequences:
    for y in valid_sequences:
        if all(sum(x[i] * x[(i+k) % 23] for i in range(23)) + sum(y[i] * y[(i+k) % 23] for i in range(23)) == -2 for k in range(1, 12)):
            print([int(i) for i in x + y])
            break
    else:
        continue
    break
else:
    print("UNSATISFIABLE")
